using Microsoft.EntityFrameworkCore;

/// <summary>
/// Cosmos DB context demonstrating required EF Core 9 breaking change fixes.
/// Apply these patterns to your separate Cosmos DB project.
/// </summary>
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change #1: Default discriminator property renamed from
        // "Discriminator" to "$type". Existing documents use the old name, so we must
        // explicitly configure it to preserve compatibility.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // EF Core 9 breaking change #2: id property no longer contains discriminator.
        // Existing documents have "Session|<key>" format. Preserve it for compatibility.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }

    // EF Core 9 breaking change #3: Sync I/O on Cosmos DB provider now throws.
    // All queries and SaveChanges must use async equivalents.
    //
    // BEFORE (throws in EF Core 9):
    //   var sessions = db.Sessions.ToList();
    //   db.SaveChanges();
    //
    // AFTER (required fix):
    //   var sessions = await db.Sessions.ToListAsync();
    //   await db.SaveChangesAsync();
}

class Session
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

